info:
Génère des briefs de contenu SEO structurés via Claude 3 Haiku.
Trigger : inject manuel OU POST /flows/seo/brief
Payload attendu : { "keywords": ["mot-clé 1", "mot-clé 2"] }

func:
const keywords = msg.payload.keywords || [];

if (!keywords.length) {
  node.error('Aucun mot-clé fourni dans payload.keywords', msg);
  return null;
}

const keywordList = keywords.map((k, i) => `${i+1}. ${k}`).join('
');

const systemPrompt = `Tu es un expert SEO francophone spécialisé dans les marchés d'Afrique de l'Ouest (Sénégal, Côte d'Ivoire, UEMOA). Tu produis des briefs de contenu structurés, concrets et actionnables pour des articles de blog B2B.`;

const userPrompt = `Génère un brief de contenu SEO complet pour un article de blog ciblant les mots-clés suivants :
${keywordList}

Le brief doit contenir exactement ces sections :

## 🎯 Mot-clé principal
(le plus fort des mots-clés fournis)

## 📝 Titre H1 optimisé
(60-65 caractères, inclut le mot-clé principal)

## 🔍 Meta description
(150-160 caractères, inclut le mot-clé, avec appel à l'action)

## 🏗️ Plan de l'article (5 parties)
(H2 + sous-points H3 pour chaque partie, ~300-400 mots par partie)

## 💡 Angle éditorial différenciant
(En quoi cet article sera unique vs. la concurrence — contexte africain/francophone)

## 🔗 Mots-clés LSI à intégrer naturellement
(10-15 expressions sémantiquement liées)

## 📊 Intentions de recherche couvertes
(Informationnelle / Navigationnelle / Transactionnelle — pour chaque mot-clé)

## ✅ Appel à l'action suggéré
(1 CTA en lien avec KPSyDesk ITAM)

Réponds UNIQUEMENT avec le brief structuré en Markdown, sans introduction ni conclusion méta.`;

msg.claudeRequest = {
  model: 'claude-3-haiku-20240307',
  max_tokens: 2048,
  system: systemPrompt,
  messages: [{ role: 'user', content: userPrompt }]
};

msg.keywordSlug = keywords[0]
  .toLowerCase()
  .replace(/[àâä]/g, 'a').replace(/[éèêë]/g, 'e')
  .replace(/[îï]/g, 'i').replace(/[ôö]/g, 'o').replace(/[ùûü]/g, 'u')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

msg.timestamp = new Date().toISOString().slice(0, 10);

return msg;

// Récupérer la clé API depuis les credentials Node-RED
// Dans l'interface Node-RED : Manage Palette → Credentials → claude_api_key
const apiKey = flow.get('claude_api_key') || env.get('CLAUDE_API_KEY');

if (!apiKey) {
  node.error('Clé API Claude manquante. Configurer dans les credentials Node-RED : claude_api_key', msg);
  return null;
}

msg.headers = {
  'Content-Type': 'application/json',
  'x-api-key': apiKey,
  'anthropic-version': '2023-06-01'
};

msg.payload = msg.claudeRequest;
return msg;

if (msg.statusCode !== 200) {
  node.error(`Erreur API Claude ${msg.statusCode}: ${JSON.stringify(msg.payload)}`, msg);
  return null;
}

const content = msg.payload?.content?.[0]?.text || '';
if (!content) {
  node.error('Réponse Claude vide ou format inattendu', msg);
  return null;
}

const filename = `${msg.timestamp}_${msg.keywordSlug}.md`;
const header = `---\ntimestamp: ${new Date().toISOString()}\nkeyword: ${msg.keywordSlug}\nmodel: claude-3-haiku-20240307\ntokens_input: ${msg.payload.usage?.input_tokens || 'N/A'}\ntokens_output: ${msg.payload.usage?.output_tokens || 'N/A'}\n---\n\n`;

msg.filename = `/data/briefs/${filename}`;
msg.payload = header + content;
msg.topic = filename;

node.log(`Brief généré : ${filename} (${msg.payload.length} chars)`);
return msg;

// À EXÉCUTER UNE SEULE FOIS après avoir saisi la clé.
// Décommenter, injecter, puis recommenter.
// flow.set('claude_api_key', 'sk-ant-VOTRE_CLE_ICI');
node.warn('Configurer claude_api_key via Manage Palette → Context Data → flow context');
return msg;
